cat > check.mjs <<'EOF'
import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1600, height: 1000 } });
await p.goto("http://localhost:3001/analysis/G70", { waitUntil: "networkidle" });
const link = p.locator('a[href*="feature="]').first();
console.log("feature:", await link.getAttribute("href"));
await link.click();
const sec = p.locator("section", { has: p.locator("h3", { hasText: /^Customer feedback$/ }) });
await sec.locator("figure").first().waitFor({ timeout: 60000 });
const figs = sec.locator("figure");
console.log("figures:", await figs.count());
console.log("classes:", await figs.first().getAttribute("class"));
console.log("caption:", (await figs.first().locator("figcaption").innerText()).replace(/\S{20,}/g, "…").slice(0, 200));
console.log("marks:", await sec.locator("mark").count());
await sec.screenshot({ path: "sheet.png" });
const add = figs.first().getByRole("button", { name: "Add to chat" });
await add.click();
console.log("after click:", await figs.first().getByRole("button", { name: /Added/ }).count());
await b.close();
EOF
node check.mjs 2>&1 | grep -v -i warning

